// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool, IStolenNftOracle} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    MockNFT nft;

    // InvMutTest doubles as c's factory: c queries protocolFeeRate() on it.
    uint16 public protocolFeeRate = 0;

    receive() external payable {}

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        nft = new MockNFT();
    }

    function testFuzz_property(
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint256 tokenId
    ) public {
        // Admissible domain: reserves fit in uint128; keep output strictly positive.
        virtualBaseTokenReserves = uint128(bound(uint256(virtualBaseTokenReserves), 2e18, 2**126));
        // vNft < vBase ensures outputAmount = vBase*1e18/(vNft+1e18) > 0
        virtualNftReserves = uint128(bound(uint256(virtualNftReserves), 1e18, uint256(virtualBaseTokenReserves) - 1));

        // Initialize the pool: ETH base token, no merkle gate, no fees, no royalties, no oracle.
        c.initialize(
            address(0),
            address(nft),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0, // changeFee
            0, // feeRate
            bytes32(0), // merkleRoot == 0 -> weight = 1e18 per token
            false,
            false
        );

        // Fund the pool so it can pay out the ETH proceeds of the sale.
        vm.deal(address(c), type(uint128).max);

        // Seller (this test contract) owns the token being sold.
        nft.mint(tokenId);

        uint256 before = c.virtualBaseTokenReserves();

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;
        uint256[] memory tokenWeights = new uint256[](1);
        tokenWeights[0] = 1e18;
        bytes32[] memory proof = new bytes32[](0);
        bool[] memory flags = new bool[](0);
        PrivatePool.MerkleMultiProof memory mp = PrivatePool.MerkleMultiProof(proof, flags);
        IStolenNftOracle.Message[] memory stolenProofs = new IStolenNftOracle.Message[](0);

        c.sell(tokenIds, tokenWeights, mp, stolenProofs);

        // General rule: selling NFTs removes base-token reserves from the pool —
        // virtualBaseTokenReserves strictly decreases by the (positive) quote output.
        assertTrue(c.virtualBaseTokenReserves() < before);
    }
}

// Minimal permissive NFT counterparty that c's sell() drives tokens through.
contract MockNFT {
    mapping(uint256 => address) public ownerOf;

    function mint(uint256 id) external {
        ownerOf[id] = msg.sender;
    }

    function safeTransferFrom(address, address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function balanceOf(address a) external view returns (uint256) {
        return a == address(this) ? 0 : 0;
    }
}
